//! `BatchTable` against a capture of the pinned CesiumJS engine on a real
//! WebGL2 context, `tests/data/scene-batch-table.json` (generated by
//! `tools/cesium/generate-scene-batch-table.mjs`): layouts, every get, the
//! CPU values, the dirty flag, texture creation and every texture call, the
//! generated vertex shader and the uniforms. `packFloats` scenarios run on a
//! context without float textures.
//!
//! Texture calls are compared as data uploads (size, format, type and exact
//! bytes): the renderer's `Texture` issues its sampler and pixel-store calls
//! in its own order, and fills a new texture with `texSubImage2D` where
//! Cesium uses a second `texImage2D`; the texture contents are the same.

use cesium_rs::core::*;
use cesium_rs::renderer::{Context, Gl, GlValue, UniformValue};
use cesium_rs::scene::batch_table::*;
use serde_json::{json, Value};
use std::{
    cell::{Cell, RefCell},
    rc::Rc,
};

const MAX_TEXTURE_SIZE: f64 = 3379.0;

#[derive(Clone)]
struct Host {
    next: Rc<Cell<u32>>,
    float_textures: bool,
    maximum_texture_size: f64,
    calls: Rc<RefCell<Vec<Value>>>,
}

fn fnv(bytes: &[u8]) -> String {
    let mut h: u64 = 0xcbf29ce484222325;
    for b in bytes {
        h = (h ^ *b as u64).wrapping_mul(0x100000001b3);
    }
    format!("{h:x}")
}

impl Gl for Host {
    type Object = u32;
    fn drawing_buffer_size(&self) -> Result<[u32; 2], RuntimeError> {
        Ok([8, 8])
    }
    fn invoke(&self, name: &str, args: &[GlValue<u32>]) -> Result<GlValue<u32>, RuntimeError> {
        if ["texImage2D", "texSubImage2D", "texParameteri", "pixelStorei"].contains(&name) {
            let mut call = vec![json!(name)];
            call.extend(args.iter().map(|a| match a {
                GlValue::Number(n) => json!(n),
                GlValue::Bool(b) => json!(b),
                GlValue::Bytes(b) | GlValue::Pixels { bytes: b, .. } => json!([b.len(), fnv(b)]),
                GlValue::Null => Value::Null,
                other => json!(format!("{other:?}")),
            }));
            self.calls.borrow_mut().push(Value::Array(call));
        }
        let first = match args.first() {
            Some(GlValue::Number(n)) => Some(*n),
            _ => None,
        };
        Ok(if name.starts_with("create") {
            self.next.set(self.next.get() + 1);
            GlValue::Object(self.next.get())
        } else {
            match name {
                "getParameter" if first == Some(MAX_TEXTURE_SIZE) => GlValue::Number(self.maximum_texture_size),
                "getParameter" if matches!(first, Some(33901.) | Some(33902.) | Some(3386.)) => {
                    GlValue::Numbers(vec![1., 4096.])
                }
                "getParameter" => GlValue::Number(4096.),
                "getExtension" => match args.first() {
                    Some(GlValue::String(s)) if s.contains("float") && !self.float_textures => GlValue::Null,
                    _ => GlValue::Object(0),
                },
                "getShaderParameter" | "getProgramParameter" => GlValue::Bool(true),
                _ => GlValue::Null,
            }
        })
    }
}

fn num(v: &Value) -> f64 {
    match v.as_str() {
        Some("Infinity") => f64::INFINITY,
        Some("-Infinity") => f64::NEG_INFINITY,
        Some("NaN") => f64::NAN,
        _ => v.as_f64().unwrap(),
    }
}

fn value(v: &Value) -> BatchValue {
    match v.as_array() {
        None => BatchValue::Scalar(num(v)),
        Some(a) => {
            let n: Vec<f64> = a.iter().map(num).collect();
            match n.len() {
                2 => BatchValue::Vec2(Cartesian2::new(n[0], n[1])),
                3 => BatchValue::Vec3(Cartesian3::new(n[0], n[1], n[2])),
                _ => BatchValue::Vec4(Cartesian4::new(n[0], n[1], n[2], n[3])),
            }
        }
    }
}

fn encode(v: BatchValue) -> Value {
    match v {
        BatchValue::Scalar(x) => json!(x),
        BatchValue::Vec2(c) => json!([c.x, c.y]),
        BatchValue::Vec3(c) => json!([c.x, c.y, c.z]),
        BatchValue::Vec4(c) => json!([c.x, c.y, c.z, c.w]),
    }
}

/// Numbers compare by value whatever their JSON spelling.
fn same(a: &Value, b: &Value) -> bool {
    match (a, b) {
        (Value::Number(_), Value::Number(_)) => a.as_f64() == b.as_f64(),
        (Value::Array(a), Value::Array(b)) => a.len() == b.len() && a.iter().zip(b).all(|(a, b)| same(a, b)),
        _ => a == b,
    }
}

/// Data-carrying `texImage2D`/`texSubImage2D` calls as
/// `[width, height, format, type, [length, hash]]`.
fn uploads(calls: &[Value]) -> Vec<Value> {
    calls
        .iter()
        .filter_map(|c| {
            let c = c.as_array().unwrap();
            let data = c.last().unwrap();
            if !data.is_array() {
                return None;
            }
            match c[0].as_str().unwrap() {
                // target, level, internalformat, width, height, border, format, type, data
                "texImage2D" => Some(json!([c[4], c[5], c[7], c[8], data])),
                // target, level, x, y, width, height, format, type, data
                "texSubImage2D" => Some(json!([c[5], c[6], c[7], c[8], data])),
                _ => None,
            }
        })
        .collect()
}

fn datatype(v: &Value) -> ComponentDatatype {
    match v.as_u64().unwrap() {
        5121 => ComponentDatatype::UnsignedByte,
        5123 => ComponentDatatype::UnsignedShort,
        _ => ComponentDatatype::Float,
    }
}

#[test]
fn layouts_values_textures_and_shaders_match_cesium() {
    let fixture: Value = serde_json::from_str(include_str!("data/scene-batch-table.json")).unwrap();
    let capture = &fixture["capture"];
    let vertex_shader = fixture["vertexShader"].as_str().unwrap();
    let mut steps_checked = 0;
    for (name, scenario) in fixture["scenarios"].as_object().unwrap() {
        let expected = &capture["scenarios"][name];
        let host = Host {
            next: Rc::default(),
            float_textures: scenario["packFloats"] != true,
            maximum_texture_size: capture["maximumTextureSize"].as_f64().unwrap(),
            calls: Rc::default(),
        };
        // Without float textures: WebGL 1 lacking OES_texture_float.
        let context =
            if host.float_textures { Context::new_webgl2(host.clone()) } else { Context::new_webgl1(host.clone()) };
        let attributes: Vec<BatchTableAttribute> = scenario["attributes"]
            .as_array()
            .unwrap()
            .iter()
            .map(|a| BatchTableAttribute {
                function_name: a[0].as_str().unwrap().into(),
                component_datatype: datatype(&a[1]),
                components_per_attribute: a[2].as_u64().unwrap() as u32,
                normalize: a[3].as_bool().unwrap(),
            })
            .collect();
        let mut table =
            BatchTable::new(&context, attributes, scenario["instances"].as_u64().unwrap() as usize).unwrap();

        let l = &expected["layout"];
        match table.layout() {
            None => assert!(l["stride"].is_null(), "{name}: layout"),
            Some(layout) => {
                assert_eq!(json!(layout.offsets), l["offsets"], "{name}: offsets");
                assert_eq!(json!(layout.stride), l["stride"], "{name}: stride");
                assert_eq!(json!(layout.pack_floats), l["packFloats"], "{name}: packFloats");
                assert_eq!(json!(layout.pixel_datatype as u32), l["pixelDatatype"], "{name}: pixelDatatype");
                assert!(
                    same(&json!([layout.dimensions.x, layout.dimensions.y]), &l["dimensions"]),
                    "{name}: dimensions"
                );
                let s = layout.step;
                assert!(same(&json!([s.x, s.y, s.z, s.w]), &l["step"]), "{name}: step");
                let kind = match table.batch_values().unwrap() {
                    BatchValues::Float(_) => "Float32Array",
                    BatchValues::Bytes(_) => "Uint8Array",
                };
                assert_eq!(json!(kind), l["batchValuesType"], "{name}: batch values type");
            }
        }

        for (i, (op, e)) in
            scenario["ops"].as_array().unwrap().iter().zip(expected["steps"].as_array().unwrap()).enumerate()
        {
            let ctx = format!("{name} op {i} {op}");
            host.calls.borrow_mut().clear();
            let index = |k: usize| op[k].as_u64().unwrap() as usize;
            match op[0].as_str().unwrap() {
                "set" => table.set_batched_attribute(index(1), index(2), value(&op[3])).unwrap(),
                "get" => {
                    let got = encode(table.get_batched_attribute(index(1), index(2)).unwrap());
                    assert!(same(&got, &e["value"]), "{ctx}: value {got} != {}", e["value"]);
                }
                _ => table.update(&context).unwrap(),
            }
            if table.layout().is_some() {
                assert_eq!(json!(table.is_dirty()), e["dirty"], "{ctx}: dirty");
                assert_eq!(json!(fnv(&table.batch_values().unwrap().bytes())), e["batchValues"], "{ctx}: values");
            }
            let texture = table.texture().map(|t| json!([t.width(), t.height(), t.pixel_datatype() as u32]));
            assert_eq!(texture.unwrap_or(Value::Null), e["texture"], "{ctx}: texture");
            let calls = Value::Array(uploads(&host.calls.borrow()));
            let wanted = Value::Array(uploads(e["calls"].as_array().unwrap()));
            assert!(same(&calls, &wanted), "{ctx}: texture uploads\n actual   {calls}\n expected {wanted}");
            steps_checked += 1;
        }

        assert_eq!(
            table.vertex_shader_callback()(vertex_shader),
            expected["shader"].as_str().unwrap(),
            "{name}: shader"
        );
        let mut names = vec!["existing"];
        names.extend(table.uniform_names());
        assert_eq!(json!(names), expected["uniforms"], "{name}: uniforms");
        if let Some(u) = expected["uniformValues"].as_object() {
            let values = table.uniform_values();
            let get = |n: &str| match &values.iter().find(|(k, _)| k == n).unwrap().1 {
                UniformValue::Float(v) => v.clone(),
                other => panic!("{other:?}"),
            };
            let f32s = |v: &Value| v.as_array().unwrap().iter().map(|x| num(x) as f32).collect::<Vec<_>>();
            assert_eq!(get("batchTextureDimensions"), f32s(&u["dimensions"]), "{name}: dimensions uniform");
            assert_eq!(get("batchTextureStep"), f32s(&u["step"]), "{name}: step uniform");
            assert_eq!(table.texture().is_some(), u["texture"] == true, "{name}: texture uniform");
        }
        table.destroy().unwrap();
    }
    assert_eq!(steps_checked, 55);
}

#[test]
fn range_checks() {
    let host = Host { next: Rc::default(), float_textures: true, maximum_texture_size: 4096., calls: Rc::default() };
    let context = Context::new_webgl2(host);
    let attribute = BatchTableAttribute {
        function_name: "f".into(),
        component_datatype: ComponentDatatype::UnsignedByte,
        components_per_attribute: 1,
        normalize: false,
    };
    let mut table = BatchTable::new(&context, vec![attribute], 2).unwrap();
    assert_eq!(table.get_batched_attribute(2, 0).unwrap_err().message, "instanceIndex is out of range.");
    assert_eq!(table.set_batched_attribute(0, 1, 1.0).unwrap_err().message, "attributeIndex is out of range");
}
